pub enum StlMutation {
    SetSnapshot(set_snapshot::SetSnapshot),
    PatchSnapshot(patch_snapshot::PatchSnapshot),
    SetSolidName(set_solid_name::SetSolidName),
    InsertTriangle(insert_triangle::InsertTriangle),
